               ПроверяемыеРеквизиты.Удалить(Индекс);
          КонецЕсли;
          Индекс = 0;

         Для Каждого ТекСтрокаПереченьНоменклатуры Из ПереченьНоменклатуры Цикл
              Если ТекСтрокаПереченьНоменклатуры.Номенклатура.ВидНоменклатуры =
                              Перечисления.ВидыНоменклатуры.Материал Тогда
                   Если Не ЗначениеЗаполнено(
                                   ТекСтрокаПереченьНоменклатуры.НаборСвойств) Тогда
                       Сообщение = Новый СообщениеПользователю();
                         Сообщение.Текст = "В строке " + Строка(Индекс+1) +
                                                    " списка Перечень номенклатуры не заполнена колонка Набор свойств";
                        Сообщение.Поле = "ПереченьНоменклатуры[" + Строка(Индекс) +
                                                                    "].НаборСвойств";
                         Сообщение.УстановитьДанные(ЭтотОбъект);
                         Сообщение.Сообщить();

                          Отказ = Истина;
